CREATE TABLE `design_versions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`window_id` integer NOT NULL,`version` integer NOT NULL,`measurement_version_id` integer NOT NULL,`fabric_version_ids_json` text DEFAULT '[]' NOT NULL,`hardware_part_ids_json` text DEFAULT '[]' NOT NULL,`combination_type` text NOT NULL,`configuration_json` text NOT NULL,`status` text DEFAULT 'draft' NOT NULL,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE UNIQUE INDEX `design_versions_window_version_unique` ON `design_versions` (`window_id`,`version`); CREATE INDEX `design_versions_window_idx` ON `design_versions` (`window_id`);
